// This code was generated by AI

document.addEventListener("DOMContentLoaded", () => {
    document
        .getElementById("searchBtn")
        .addEventListener("click", getWeather);

    loadFavourites();
});

async function getErrorMessage(response, fallbackMessage) {
    let data;

    try {
        data = await response.json();
    }
    catch (error) {
        console.error("Could not read service error response:", error);
    }

    if (data && typeof data.error === "string" && data.error.trim()) {
        return data.error;
    }

    if (response.status >= 500) {
        return "The service is temporarily unavailable. Please try again later.";
    }

    if (response.status === 404) {
        return "The requested resource was not found.";
    }

    if (response.status === 400) {
        return "The request was invalid. Please check the selected city.";
    }

    return fallbackMessage;
}

function showError(elementId, message) {
    const element = document.getElementById(elementId);
    element.textContent = message;
    element.hidden = false;
}

function clearError(elementId) {
    const element = document.getElementById(elementId);
    element.textContent = "";
    element.hidden = true;
}

async function getWeather() {

    const city = document
        .getElementById("citySelect")
        .value
        .trim();

    if (!city) {
        showError("weatherResult", "Please select a city.");
        return;
    }

    clearError("favouritesError");

    try {

        const response = await fetch(
            `weather?city=${encodeURIComponent(city)}`
        );

        if (!response.ok) {
            throw new Error(await getErrorMessage(
                response,
                "Could not retrieve weather data."
            ));
        }

        const data = await response.json();

        document.getElementById("weatherResult").innerHTML = `
            <h2>${data.city}</h2>
            <p>Description: ${data.description}</p>
            <p>Temperature: ${data.temperature} °C</p>
            <p>Feels like: ${data.feels_like} °C</p>
            <p>Wind Speed: ${data.wind_speed} m/s</p>

            <button onclick="addFavourite('${city}')">
                Add Favourite
            </button>
        `;
    }
    catch (error) {
        console.error(error);

        showError(
            "weatherResult",
            error.message === "Failed to fetch"
                ? "The weather service is unavailable. Please try again later."
                : error.message
        );
    }
}

async function addFavourite(city) {

    try {

        const response = await fetch(
            `/addFavourite?city=${encodeURIComponent(city)}`
        );

        if (!response.ok) {
            throw new Error(await getErrorMessage(
                response,
                "Could not add this city to favourites."
            ));
        }

        clearError("favouritesError");
        loadFavourites();
    }
    catch (error) {
        console.error(error);
        showError(
            "favouritesError",
            error.message === "Failed to fetch"
                ? "The favourites service is unavailable. Please try again later."
                : error.message
        );
    }
}

async function removeFavourite(city) {

    try {

        const response = await fetch(
            `/removeFavourite?city=${encodeURIComponent(city)}`
        );

        if (!response.ok) {
            throw new Error(await getErrorMessage(
                response,
                "Could not remove this city from favourites."
            ));
        }

        clearError("favouritesError");
        loadFavourites();
    }
    catch (error) {
        console.error(error);
        showError(
            "favouritesError",
            error.message === "Failed to fetch"
                ? "The favourites service is unavailable. Please try again later."
                : error.message
        );
    }
}

function showFavourite(city) {
    const citySelect = document.getElementById("citySelect");
    const cityOption = Array.from(citySelect.options)
        .find((option) => option.value === city);

    if (!cityOption) {
        document.getElementById("weatherResult").innerHTML =
            "<p>This favourite is no longer available in the city list.</p>";
        return;
    }

    citySelect.value = city;
    getWeather();
}

async function loadFavourites() {

    try {

        const response = await fetch(
            `/getFavourites`
        );

        if (!response.ok) {
            throw new Error(await getErrorMessage(
                response,
                "Could not load favourites."
            ));
        }

        const data = await response.json();

        let html = "";

        for (const city of data.favouritesFromStore) {

            html += `
                <li>
                    ${city}

                    <button onclick="showFavourite('${city}')">
                        Show
                    </button>

                    <button onclick="removeFavourite('${city}')">
                        Remove
                    </button>
                </li>
            `;
        }

        document.getElementById("favouritesList").innerHTML = html;
    }
    catch (error) {
        console.error(error);
        showError(
            "favouritesError",
            error.message === "Failed to fetch"
                ? "The favourites service is unavailable. Please try again later."
                : error.message
        );
    }
}